import React, { useState } from "react";
import Layout from "../components/Layout";
import api from "../services/api";

const Prescription = () => {
    const [formData, setFormData] = useState({
        name: "",
        medicines: [{ medicine: "", dosage: "", days: "" }],
    });

    // Handle Patient Name Change
    const handlePatientChange = (e) => {
        setFormData({
            ...formData,
            name: e.target.value,
        });
    };

    // Handle Medicine Row Change
    const handleMedicineChange = (index, field, value) => {
        const updatedMedicines = [...formData.medicines];
        updatedMedicines[index][field] = value;

        setFormData({
            ...formData,
            medicines: updatedMedicines,
        });
    };

    // Add New Medicine Row
    const addMedicineRow = () => {
        setFormData({
            ...formData,
            medicines: [...formData.medicines, { medicine: "", dosage: "", days: "" }],
        });
    };

    // Remove Medicine Row
    const removeMedicineRow = (index) => {
        const updatedMedicines = formData.medicines.filter((_, i) => i !== index);

        setFormData({
            ...formData,
            medicines: updatedMedicines,
        });
    };

    // Generate PDF Prescription
    const handleSubmit = async (e) => {
        e.preventDefault();

        try {
            const res = await api.post(
                "/prescription/pdf",
                formData,
                { responseType: "blob" } // Important for PDF
            );

            // Download PDF File
            const file = new Blob([res.data], { type: "application/pdf" });
            const link = document.createElement("a");
            link.href = window.URL.createObjectURL(file);
            link.download = "prescription.pdf";
            link.click();

            alert("✅ Prescription PDF Generated Successfully");
        } catch (error) {
            console.log("Error generating prescription PDF:", error);
            alert("❌ Failed to Generate Prescription PDF");
        }
    };

    return (
        <Layout>
            <div className="container-fluid">

                {/* Page Header */}
                <h2 className="fw-bold mb-4 text-primary">
                    💊 Prescription Generator (Multiple Medicines)
                </h2>

                {/* Prescription Form */}
                <div className="card shadow-lg border-0">
                    <div className="card-header bg-primary text-white fw-bold">
                        Create Prescription PDF
                    </div>

                    <div className="card-body">
                        <form onSubmit={handleSubmit}>

                            {/* Patient Name */}
                            <div className="mb-3">
                                <label className="form-label fw-semibold">
                                    Patient Name
                                </label>
                                <input
                                    type="text"
                                    className="form-control"
                                    placeholder="Enter patient name"
                                    value={formData.name}
                                    onChange={handlePatientChange}
                                    required
                                />
                            </div>

                            {/* Medicines Section */}
                            <h5 className="fw-bold mt-4 mb-3">
                                💊 Medicines List
                            </h5>

                            {formData.medicines.map((med, index) => (
                                <div key={index} className="row g-2 mb-2 align-items-center">

                                    {/* Medicine Name */}
                                    <div className="col-md-4">
                                        <input
                                            type="text"
                                            className="form-control"
                                            placeholder="Medicine Name"
                                            value={med.medicine}
                                            onChange={(e) =>
                                                handleMedicineChange(index, "medicine", e.target.value)
                                            }
                                            required
                                        />
                                    </div>

                                    {/* Dosage */}
                                    <div className="col-md-3">
                                        <input
                                            type="text"
                                            className="form-control"
                                            placeholder="Dosage (1-0-1)"
                                            value={med.dosage}
                                            onChange={(e) =>
                                                handleMedicineChange(index, "dosage", e.target.value)
                                            }
                                            required
                                        />
                                    </div>

                                    {/* Days */}
                                    <div className="col-md-3">
                                        <input
                                            type="number"
                                            className="form-control"
                                            placeholder="Days"
                                            value={med.days}
                                            onChange={(e) =>
                                                handleMedicineChange(index, "days", e.target.value)
                                            }
                                            required
                                        />
                                    </div>

                                    {/* Remove Button */}
                                    <div className="col-md-2">
                                        {formData.medicines.length > 1 && (
                                            <button
                                                type="button"
                                                className="btn btn-danger w-100"
                                                onClick={() => removeMedicineRow(index)}
                                            >
                                                ❌ Remove
                                            </button>
                                        )}
                                    </div>

                                </div>
                            ))}

                            {/* Add Medicine Button */}
                            <button
                                type="button"
                                className="btn btn-outline-primary mt-3"
                                onClick={addMedicineRow}
                            >
                                ➕ Add Another Medicine
                            </button>

                            {/* Generate PDF Button */}
                            <div className="text-end mt-4">
                                <button type="submit" className="btn btn-success px-4">
                                    📄 Generate Prescription PDF
                                </button>
                            </div>

                        </form>
                    </div>
                </div>

            </div>
        </Layout>
    );
};

export default Prescription;
